and mapObligationBody (value: S.ObligationBody) : Fidelity.PSG.ObligationBody =
    match value with
    | S.ObligationBody.Pending reasons -> invalidOp ("A pending obligation cannot be published: " + String.concat "; " reasons)
    | S.ObligationBody.ProgramInitializationOrder(a0, a1, a2) -> Fidelity.PSG.ObligationBody.ProgramInitializationOrder(a0, a1, a2)
    | S.ObligationBody.FiniteLoopTrip(a0) -> Fidelity.PSG.ObligationBody.FiniteLoopTrip(mapFiniteLoopTripModel a0)
    | S.ObligationBody.FiniteSequencePull(a0) -> Fidelity.PSG.ObligationBody.FiniteSequencePull(mapFiniteSequencePullModel a0)
    | S.ObligationBody.AdditiveLoopInvariant(a0) -> Fidelity.PSG.ObligationBody.AdditiveLoopInvariant(mapAdditiveLoopInvariantModel a0)
    | S.ObligationBody.MappedElementSpan(a0) -> Fidelity.PSG.ObligationBody.MappedElementSpan(mapMappedSpanModel a0)
    | S.ObligationBody.IntegerLiteralRange(a0, a1, a2) -> Fidelity.PSG.ObligationBody.IntegerLiteralRange(a0, a1, a2)
    | S.ObligationBody.IntegerRepresentationCoverage(a0, a1, a2, a3) -> Fidelity.PSG.ObligationBody.IntegerRepresentationCoverage(a0, a1, a2, a3)
    | S.ObligationBody.IntegerDivisorNonzero(a0, a1) -> Fidelity.PSG.ObligationBody.IntegerDivisorNonzero(a0, a1)
    | S.ObligationBody.IntegerShiftCount(a0, a1, a2) -> Fidelity.PSG.ObligationBody.IntegerShiftCount(a0, a1, a2)
    | S.ObligationBody.SpatialKernelPartition(a0, a1, a2, a3, a4, a5) -> Fidelity.PSG.ObligationBody.SpatialKernelPartition(a0, a1, a2, a3, a4, a5)
    | S.ObligationBody.ApplicationDimensions(a0) -> Fidelity.PSG.ObligationBody.ApplicationDimensions((a0 |> List.map (fun x -> (let (t0, t1, t2) = x in (t0, (t1 |> Option.map (fun x -> mapDimension x)), (t2 |> Option.map (fun x -> mapDimension x)))))))
    | S.ObligationBody.RealLiteralRange(a0, a1, a2) -> Fidelity.PSG.ObligationBody.RealLiteralRange(mapExactRational a0, mapExactRational a1, mapExactRational a2)
    | S.ObligationBody.RealRepresentationCoverage(a0, a1, a2, a3) -> Fidelity.PSG.ObligationBody.RealRepresentationCoverage(mapExactRational a0, mapExactRational a1, mapExactRational a2, mapExactRational a3)
    | S.ObligationBody.DimensionalRelation(a0, a1, a2, a3) -> Fidelity.PSG.ObligationBody.DimensionalRelation(mapDimensionalRule a0, mapDimension a1, mapDimension a2, (a3 |> Option.map (fun x -> mapDimension x)))
    | S.ObligationBody.StorageReservation(a0, a1) -> Fidelity.PSG.ObligationBody.StorageReservation(a0, a1)
    | S.ObligationBody.ViewContainment(a0, a1, a2) -> Fidelity.PSG.ObligationBody.ViewContainment(a0, a1, a2)
    | S.ObligationBody.NulSentinel(a0) -> Fidelity.PSG.ObligationBody.NulSentinel(a0)
    | S.ObligationBody.ConsecutiveLayout(a0, a1, a2) -> Fidelity.PSG.ObligationBody.ConsecutiveLayout(a0, a1, a2)
    | S.ObligationBody.StaticStorageLayout(a0, a1, a2, a3, a4, a5, a6) -> Fidelity.PSG.ObligationBody.StaticStorageLayout(a0, a1, a2, a3, a4, a5, a6)
    | S.ObligationBody.ContinuationLayout(a0, a1, a2) -> Fidelity.PSG.ObligationBody.ContinuationLayout(a0, a1, a2)
    | S.ObligationBody.EnvironmentStorageReservation(a0, a1, a2, a3, a4) -> Fidelity.PSG.ObligationBody.EnvironmentStorageReservation(a0, a1, a2, a3, a4)
    | S.ObligationBody.ConcatCopyBound(a0, a1) -> Fidelity.PSG.ObligationBody.ConcatCopyBound(a0, a1)
    | S.ObligationBody.CapacityPositive(a0) -> Fidelity.PSG.ObligationBody.CapacityPositive(a0)
    | S.ObligationBody.CapacityFits(a0, a1) -> Fidelity.PSG.ObligationBody.CapacityFits(a0, a1)
    | S.ObligationBody.InputBufferBound(a0, a1) -> Fidelity.PSG.ObligationBody.InputBufferBound(a0, a1)
    | S.ObligationBody.StringBorrowBound(a0) -> Fidelity.PSG.ObligationBody.StringBorrowBound(a0)
    | S.ObligationBody.InputCopyBound(a0, a1) -> Fidelity.PSG.ObligationBody.InputCopyBound(a0, a1)
    | S.ObligationBody.FiniteLinearRecurrence(a0) -> Fidelity.PSG.ObligationBody.FiniteLinearRecurrence(mapFiniteLinearRecurrenceModel a0)
    | S.ObligationBody.FiniteAdditiveEffects(a0, a1, a2, a3) -> Fidelity.PSG.ObligationBody.FiniteAdditiveEffects(a0, a1, a2, a3)
    | S.ObligationBody.ForeignResultCoverage(a0) -> Fidelity.PSG.ObligationBody.ForeignResultCoverage(mapForeignResultCoverageModel a0)
    | S.ObligationBody.ResourceConversion(a0) -> Fidelity.PSG.ObligationBody.ResourceConversion(mapResourceConversionModel a0)
    | S.ObligationBody.ResourceCleanup(a0) -> Fidelity.PSG.ObligationBody.ResourceCleanup(mapResourceCleanupModel a0)
    | S.ObligationBody.SnapshotBorrowBound(a0, a1, a2, a3, a4, a5) -> Fidelity.PSG.ObligationBody.SnapshotBorrowBound(nodeId a0, nodeId a1, nodeId a2, nodeId a3, a4, a5)

