and mapPattern (value: S.Pattern) : Fidelity.PSG.Pattern =
    match value with
    | S.Pattern.Const(a0) -> Fidelity.PSG.Pattern.Const(mapNativeLiteral a0)
    | S.Pattern.Var(a0, a1) -> Fidelity.PSG.Pattern.Var(a0, freeze a1)
    | S.Pattern.Wildcard -> Fidelity.PSG.Pattern.Wildcard
    | S.Pattern.Tuple(a0) -> Fidelity.PSG.Pattern.Tuple((a0 |> List.map (fun x -> mapPattern x)))
    | S.Pattern.Union(a0, a1, a2, a3) -> Fidelity.PSG.Pattern.Union(a0, a1, (a2 |> Option.map (fun x -> mapPattern x)), freeze a3)
    | S.Pattern.Record(a0, a1) -> Fidelity.PSG.Pattern.Record((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapPattern t1)))), freeze a1)
    | S.Pattern.Array(a0) -> Fidelity.PSG.Pattern.Array((a0 |> List.map (fun x -> mapPattern x)))
    | S.Pattern.Or(a0, a1) -> Fidelity.PSG.Pattern.Or(mapPattern a0, mapPattern a1)
    | S.Pattern.And(a0, a1) -> Fidelity.PSG.Pattern.And(mapPattern a0, mapPattern a1)
    | S.Pattern.As(a0, a1) -> Fidelity.PSG.Pattern.As(mapPattern a0, a1)
