    match value with
    | N.TypeLayout.Inline(a0, a1) -> Fidelity.PSG.TypeLayout.Inline(a0, a1)
    | N.TypeLayout.Reference(a0) -> Fidelity.PSG.TypeLayout.Reference(mapArenaAffinity a0)
    | N.TypeLayout.Opaque -> Fidelity.PSG.TypeLayout.Opaque
    | N.TypeLayout.PlatformWord -> Fidelity.PSG.TypeLayout.PlatformWord
    | N.TypeLayout.FatPointer -> Fidelity.PSG.TypeLayout.FatPointer
    | N.TypeLayout.NTUCompound(a0) -> Fidelity.PSG.TypeLayout.NTUCompound(a0)
    | N.TypeLayout.Qualified(a0, a1) -> Fidelity.PSG.TypeLayout.Qualified(mapTypeLayout a0, mapNTUQualifiers a1)
    | N.TypeLayout.Record -> Fidelity.PSG.TypeLayout.Record
    | N.TypeLayout.Union -> Fidelity.PSG.TypeLayout.Union

and mapTypeParamKind (value: N.TypeParamKind) : Fidelity.PSG.TypeParamKind =
    match value with
    | N.TypeParamKind.Type -> Fidelity.PSG.TypeParamKind.Type
    | N.TypeParamKind.Measure -> Fidelity.PSG.TypeParamKind.Measure
    | N.TypeParamKind.Carrier -> Fidelity.PSG.TypeParamKind.Carrier

and mapValueRange (value: N.ValueRange) : Fidelity.PSG.ValueRange =
    match value with
    | N.ValueRange.Empty -> Fidelity.PSG.ValueRange.Empty
    | N.ValueRange.Bounded(a0, a1) -> Fidelity.PSG.ValueRange.Bounded(a0, a1)
    | N.ValueRange.Above(a0) -> Fidelity.PSG.ValueRange.Above(a0)
    | N.ValueRange.Below(a0) -> Fidelity.PSG.ValueRange.Below(a0)
    | N.ValueRange.Unbounded -> Fidelity.PSG.ValueRange.Unbounded

and mapValueRepresentation (value: S.ValueRepresentation) : Fidelity.PSG.ValueRepresentation =
    match value with
    | S.ValueRepresentation.Scalar(a0) -> Fidelity.PSG.ValueRepresentation.Scalar(mapSettledSlot a0)
    | S.ValueRepresentation.Buffer(a0, a1) -> Fidelity.PSG.ValueRepresentation.Buffer(a0, mapValueRepresentation a1)
    | S.ValueRepresentation.Record(a0, a1) -> Fidelity.PSG.ValueRepresentation.Record((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, mapValueRepresentation t1)))), a1)
    | S.ValueRepresentation.CallableComponent(a0, a1) -> Fidelity.PSG.ValueRepresentation.CallableComponent(nodeId a0, mapValueRepresentation a1)
    | S.ValueRepresentation.Union(a0, a1) -> Fidelity.PSG.ValueRepresentation.Union((a0 |> List.map (fun x -> (let (t0, t1) = x in (t0, (t1 |> List.map (fun x -> mapValueRepresentation x)))))), a1)
    | S.ValueRepresentation.Tag(a0) -> Fidelity.PSG.ValueRepresentation.Tag(a0)

and mapWidthDimension (value: N.WidthDimension) : Fidelity.PSG.WidthDimension =
    match value with
    | N.WidthDimension.Pointer -> Fidelity.PSG.WidthDimension.Pointer
    | N.WidthDimension.Register -> Fidelity.PSG.WidthDimension.Register

and mapWitnessEmissionProjection (value: S.WitnessEmissionProjection) : Fidelity.PSG.WitnessEmissionProjection =
    ({
        Ordinary = mapOrdinaryDemandProjection value.Ordinary
        Callable = mapCallableEmissionProjection value.Callable
        Storage = mapStorageWitnessProjection value.Storage
        Boundary = mapBoundaryEmissionProjection value.Boundary
        Numeric = mapNumericWitnessProjection value.Numeric
        Memory = mapMemoryWitnessProjection value.Memory
        Spatial = mapSpatialModuleProjection value.Spatial
    } : Fidelity.PSG.WitnessEmissionProjection)

and mapWitnessRegion (value: S.WitnessRegion) : Fidelity.PSG.WitnessRegion =
    ({
        Identity = value.Identity
        Flavor = mapWitnessRegionKind value.Flavor
        Root = (value.Root |> Option.map (fun x -> nodeId x))
        Anchor = (value.Anchor |> Option.map (fun x -> nodeId x))
        Path = (value.Path |> List.map (fun x -> mapOccurrenceBreadcrumb x))
        Members = (value.Members |> Set.map (fun x -> nodeId x))
        Supports = (value.Supports |> Set.map (fun x -> nodeId x))
        OwnerSupport = mapWitnessScopeSupport value.OwnerSupport
        Fingerprint = value.Fingerprint
        Dependencies = value.Dependencies
    } : Fidelity.PSG.WitnessRegion)

and mapWitnessRegionKind (value: S.WitnessRegionKind) : Fidelity.PSG.WitnessRegionKind =
    match value with
    | S.WitnessRegionKind.Common -> Fidelity.PSG.WitnessRegionKind.Common
    | S.WitnessRegionKind.ScalarCallable -> Fidelity.PSG.WitnessRegionKind.ScalarCallable

and mapWitnessSegmentation (value: S.WitnessSegmentation) : Fidelity.PSG.WitnessSegmentation =
    ({
        Version = value.Version
        Regions = (value.Regions |> List.map (fun x -> mapWitnessRegion x))
    } : Fidelity.PSG.WitnessSegmentation)

/// A checker type crosses as its identity, with the current substitution applied.
and freeze (value: N.NativeType) : Fidelity.PSG.TypeIdentity =
    mapTypeIdentity (Clef.Compiler.NativeTypedTree.TypeIdentities.ofType value)

/// The source policy is explicit; this stamp grants no accepted proof authority.
and mapWitnessScopeSupport (value: S.WitnessScopeSupport) : Fidelity.PSG.SupportKey =
    match value.Policy with
    | S.WitnessScopeSupportPolicy.WholePreparedOwner -> Fidelity.PSG.SupportKey.WholeOwningAnalysisRegion value.Identity
// END GENERATED MAPPERS; typed Baker source-reading assembly follows.
/// Copy Baker's prepared foreign storage rows; declaration readers never run here.
let mapWitnessForeignStorage (value: S.WitnessForeignStorage) : Fidelity.PSG.ForeignStorageProjection =
    let layout (row: S.WitnessBorrowedViewLayout) : Fidelity.PSG.BorrowedViewLayout =
        { Schema = row.Schema; ElementBits = row.ElementBits; Range = mapValueRange row.Range
          Alignment = row.Alignment; Access = row.Access }
    let borrowed (row: S.WitnessBorrowedViewOperation) : Fidelity.PSG.BorrowedViewOperation =
        { Site = nodeId row.Site; Operation = row.Operation; View = nodeId row.View
          Arguments = List.map nodeId row.Arguments; Layout = Result.map layout row.Layout
          Span = Result.map mapMappedSpanModel row.Span }
    let mmio (row: S.WitnessMmioOperation) : Fidelity.PSG.MmioOperation =
        { Site = nodeId row.Site; Operation = row.Operation; Arguments = List.map nodeId row.Arguments }
    let rows map table = table |> Map.toSeq |> Seq.map (fun (id, row) -> nodeId id, map row) |> Map.ofSeq
    { BorrowedViews = rows borrowed value.BorrowedViews; Mmio = rows mmio value.Mmio
      MappedCalls = Set.map nodeId value.MappedCalls }

let mapWitnessExplicitDemand (value: S.WitnessExplicitDemand) : Fidelity.PSG.ExplicitDemandProjection =
    let relation (row: S.WitnessEagerDemandRelation) : Fidelity.PSG.EagerDemandRelation =
        { Sources = List.map nodeId row.Sources; Ordinal = row.Ordinal
          Frontier = Option.map mapEagerFrontier row.Frontier; IsDemand = row.IsDemand }
    { Operands = value.Operands |> Map.toSeq |> Seq.map (fun (id, operand) -> nodeId id, nodeId operand) |> Map.ofSeq
      Relations = value.Relations |> Map.toSeq |> Seq.map (fun (id, rows) -> nodeId id, List.map relation rows) |> Map.ofSeq }

/// Copy Baker's explicit entries, compact contexts and resolved-use account.
/// No reader or publication mapper discovers roots or demands declaration bodies.
let mapWitnessSourceReadings (value: S.WitnessLiveScopePlan) : Fidelity.PSG.WitnessSourceReadings =
    let child (row: S.WitnessChildDisposition) : Fidelity.PSG.ChildDisposition =
        { Ordinal = row.Ordinal
          Traversal =
            match row.Traversal with
            | S.WitnessChildTraversal.SourceLive id -> Fidelity.PSG.ChildTraversal.EnterLocal(nodeId id)
            | S.WitnessChildTraversal.SourceOmitted(support, id) ->
                Fidelity.PSG.ChildTraversal.SourceOmitted(mapWitnessScopeSupport support, nodeId id) }
    let rows map table = table |> Map.toSeq |> Seq.map (fun (id, row) -> nodeId id, map row) |> Map.ofSeq
    { Entries = List.map mapSourceWitnessEntry value.Entries
      Children = value.Occurrences |> rows (fun (row: S.WitnessLiveOccurrence) -> List.map child row.Children)
      Contexts = value.Contexts |> rows (List.map (List.map mapOccurrenceBreadcrumb))
      ContextHeaders = rows mapSourceContextHeader value.ContextHeaders
      Ports = value.Ports |> Map.toSeq |> Seq.map (fun ((owner, key), row) ->
          (nodeId owner, mapOccurrencePort key), mapSourcePortAccount row) |> Map.ofSeq
      BindingUses = rows mapBindingUseContract value.BindingUses }
